r\n  data() {\r\n    return {\r\n        base_url: window.base_url,\r\n        api_url: window.api_url, \r\n        token: this.$localStorage.get(\"d_token\"),\r\n        items:[], \r\n        item : [], \r\n        dept_users : [],\r\n        status :  '' ,\r\n        filterForm: new Form({ \r\n            year: \"\",   \r\n            month : \"\",\r\n            week : \"\", \r\n        }),\r\n      \r\n    };\r\n  },\r\n  created() {  \r\n    this.getItems();\r\n  },\r\n  methods: {\r\n    async popUp(item){\r\n        this.item =  item ;\r\n        let loader = this.$loading.show();\r\n        \r\n        await axios.get(this.api_url + \"production_emps?dept_id=\"+item.id, {\r\n                headers: {\r\n                \"Content-Type\": \"application/json\", \r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            })\r\n        .then(({ data }) => {  \r\n            loader.hide(); \r\n            this.dept_users =  data.data ;  \r\n        }); \r\n        this.$modal.show(\"popup-singel\"); \r\n    },\r\n    hide_pop() {\r\n        this.$modal.hide(\"popup-singel\");\r\n    }, \r\n    async statusChange(item , status){\r\n        let editForm =  new Form({    \r\n            status: status,\r\n            name : item.name\r\n        })\r\n        try {\r\n         let loader = this.$loading.show();\r\n            editForm.put(this.api_url + \"departments/\"+ item.id, {\r\n                headers: {\r\n                \"Content-Type\": \"application/json\", \r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            }).then((res) => {\r\n                console.log(res);\r\n                if(res.data.success){ \r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                        });\r\n                } \r\n                loader.hide(); \r\n                this.getItems();\r\n            },(error)=>{\r\n            console.log(error);\r\n            loader.hide(); \r\n            })\r\n        } catch (error) {\r\n            // loader.hide(); \r\n            console.log(error);\r\n        }\r\n    }, \r\n    async delete_row(id){ \r\n        let loader = this.$loading.show();\r\n        try {\r\n            await axios\r\n            .delete(this.api_url + \"production_emps/\"+id, {\r\n                    headers: {\r\n                    \"Content-Type\": \"application/json\", \r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                })\r\n            .then(({ res }) => {  \r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                        });\r\n                    this.getItems();\r\n               \r\n                loader.hide();\r\n            });\r\n        } catch (error) {\r\n            loader.hide();\r\n        }\r\n      },\r\n       async getItems(){\r\n           //departments_all\r\n           let loader = this.$loading.show();\r\n           let where = '?1=1';\r\n           if(this.filterForm.year){\r\n               where +='&year='+ this.filterForm.year ;\r\n           }\r\n           if(this.filterForm.month){\r\n               where +='&month='+ this.filterForm.month ;\r\n           }\r\n           if(this.filterForm.week){\r\n               where +='&week='+ this.filterForm.week ;\r\n           }\r\n           await axios.get(this.api_url + \"production_emps\"+where, {\r\n                    headers: {\r\n                    \"Content-Type\": \"application/json\", \r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                })\