 5 && filterForm.user_id\r\n                                                    !=\"\" ? 'Approved Request' : user_data.role_id == 1 ?\r\n                                                    'Approved Request' : 'Permission Request'}}\r\n\r\n                                                </button>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </section>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</template>\r\n<script>\r\nimport { Form } from \"vform\";\r\nimport axios from \"../../axios_instance\";\r\nimport Datepicker from 'vuejs-datepicker';\r\nimport Select2 from 'v-select2-component';\r\n\r\n\r\nexport default {\r\n    props: {\r\n    },\r\n    components: {\r\n        'Select2': Select2,\r\n\r\n        Datepicker,\r\n        'Select2': Select2,\r\n        // VueRecaptcha, facebookLogin\r\n    },\r\n    data() {\r\n        return {\r\n            state: {\r\n                disabledDates: {\r\n                    to: new Date(new Date().getTime() - 86400000),\r\n                    from: new Date(new Date().getTime() + (86400000 * 30))\r\n                }\r\n            },\r\n            start_date: '',\r\n            end_date: '',\r\n            jan: false,\r\n            feb: false,\r\n            mar: false,\r\n            apr: false,\r\n            may: false,\r\n            jun: false,\r\n            jul: false,\r\n            aug: false,\r\n            sep: false,\r\n            oct: false,\r\n            nov: false,\r\n            dec: false,\r\n            checked: false,\r\n            base_url: window.base_url,\r\n            api_url: window.api_url,\r\n            token: this.$localStorage.get(\"d_token\"),\r\n            user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n            role_id: '',\r\n            items: [],\r\n            deptItems: [],\r\n            status: '',\r\n            employeeItem: [],\r\n            year: this.$localStorage.get('year') ? this.$localStorage.get('year') : new Date().getFullYear(),\r\n            filterForm: new Form({\r\n                dept_id: \"\",\r\n                wing_id: \"\",\r\n                user_id: \"\"\r\n            }),\r\n            updateForm: new Form({\r\n                items: '',\r\n            }),\r\n        };\r\n    },\r\n    created() {\r\n        this.role_id = this.user_data.role_id;\r\n        // this.getItems();\r\n        this.getDept();\r\n        if (this.$route.query.user_id) {\r\n            this.filterForm.user_id = this.$route.query.user_id;\r\n        }\r\n        if (this.$route.params.id) {\r\n            this.filterForm.dept_id = this.$route.params.id;\r\n            this.getItems();\r\n        } else if (this.user_data.role_id == 5) {\r\n            this.filterForm.dept_id = this.user_data.dept_id;\r\n            this.getEmployee();\r\n            this.getItems();\r\n        } else {\r\n            this.getItems();\r\n        }\r\n\r\n    },\r\n    methods: {\r\n        async getEmployee() {\r\n            let where = '?1=1';\r\n            where += '&dept_id=' + this.user_data.dept_id;\r\n\r\n            await axios.get(this.api_url + \"users\" + where, {\r\n                headers: {\r\n                    \"Content-Type\": \"application/json\",\r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            })\r\n                .then(({ data }) => {\r\n                    this.employeeItem = data.data;\r\n                });\r\n            //}\r\n        },\r\n        changeEmployee() {\r\n            this.getItems();\r\n        },\r\n        async getDept() {\r\n            let loader = this.$loading.show();\r\n            this.getDepartments(this.status).then(({ data }) => {\r\n                if (data.success) {\r\n                    loader.hide();\r\n                    this.deptItems = data.data;\r\n                } else {\r\n                    loader.hide();\r\n                }\r\n            });\r\n        },\r\n        check(month, value) {\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index][month] = value;\r\n            }\r\n        },\r\n        datepickerClosedFunction() {\r\n\r\n        },\r\n        startDateClosedFunction() {\r\n            console.log(this.start_date);\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].start_date = this.start_date;\r\n            }\r\n\r\n        },\r\n        endDateClosedFunction() {\r\n            console.log(this.start_date);\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].end_date = this.end_date;\r\n            }\r\n        },\r\n        async statusChange(item, status) {\r\n            let editForm = new Form({\r\n                status: status,\r\n                name: item.name\r\n            })\r\n            try {\r\n                let loader = this.$loading.show();\r\n                editForm.put(this.api_url + \"departments/\" + item.id, {\r\n                    headers: {\r\n                        \"Content-Type\": \"application/json\",\r\n                        Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                }).then((res) => {\r\n                    console.log(res);\r\n                    if (res.data.success) {\r\n                        this.$toasted.show(res.data.message, {\r\n                            theme: \"bubble\",\r\n                            duration: 5000,\r\n                            position: \"bottom-right\",\r\n                        });\r\n                    }\r\n                    loader.hide();\r\n                    this.getItems();\r\n                }, (error) => {\r\n                    console.log(error);\r\n                    loader.hide();\r\n                })\r\n            } catch (error) {\r\n                // loader.hide(); \r\n                console.log(error);\r\n            }\r\n        },\r\n        update() {\r\n            let loader = this.$loading.show();\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].start_date = this.format_Date(this.items[index].start_date);\r\n                this.items[index].end_date = this.format_Date(this.items[index].end_date);\r\n            }\r\n            this.updateForm.items = this.items;\r\n            this.updateForm.year = this.year;\r\n            this.updateForm.post(this.api_url + \"m_o_s_achievement_permissions_update\", {\r\n                headers: {\r\n                    \"Content-Type\": \"application/json\",\r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            }).then((res) => {\r\n                console.log(res);\r\n                if (res.data.success) {\r\n\r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                    });\r\n                }\r\n\r\n                loader.hide();\r\n                this.getItems();\r\n                //this.$router.push('/department');\r\n            }, (error) => {\r\n                console.log(error);\r\n                loader.hide();\r\n            })\r\n\r\n        },\r\n        changeDept() {\r\n            this.getItems();\r\n\r\n        },\r\n        async getItems() {\r\n            //departments_all\r\n            let loader = this.$loading.show();\r\n            let where = \"?year=\" + this.year;\r\n            if (this.filterForm.dept_id) {\r\n                where += \"&dept_id=\" + this.filterForm.dept_id;\r\n            }\r\n            if (this.filterForm.user_id) {\r\n                where += \"&user_id=\" + this.filterForm.user_id;\r\n            }\r\n\r\n            //year\r\n\r\n            await axios.get(this.api_url + \"m_o_s_achievement_permissions\" + where, {\r\n                headers: {\r\n                    \"Content-Type\": \"application/json\",\r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            })\r\n                .then(({ data }) => {\r\n                    this.items = data.data\r\n                    loader.hide();\r\n                });\r\n\r\n        }\r\n    },\r\n    computed: {},\r\n};\r\n</script>\r\n<style>\r\n.request_status {\r\n    font-size: 11px;\r\n    background: #ec9941cc;\r\n    color: #fff;\r\n    width: 101px;\r\n    display: block;\r\n    text-align: center;\r\n    margin: 0px;\r\n    padding: 0 0 2px 0;\r\n    position: absolute;\r\n    right: 1px;\r\n    bottom: 1px;\r\n    height: 23px;\r\n    border-radius: 7px;\r\n}\r\n\r\n.request_status_appoved {\r\n    font-size: 11px;\r\n    background: #d85219ef;\r\n    color: #fff;\r\n    width: 140px;\r\n    ;\r\n    display: block;\r\n    text-align: center;\r\n    margin: 0px;\r\n    padding: 0 0 2px 0;\r\n    position: absolute;\r\n    right: 1px;\r\n    bottom: 1px;\r\n    height: 23px;\r\n    border-radius: 7px;\r\n\r\n}\r\n</style>","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./m_o_s_achievement_permissions.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.j