      </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</template>\r\n<script>\r\nimport { Form } from \"vform\";\r\nimport axios from \"../../axios_instance\";\r\nimport Datepicker from 'vuejs-datepicker';\r\nexport default {\r\n    props: {\r\n    },\r\n    components: {\r\n        Datepicker\r\n        // VueRecaptcha, facebookLogin\r\n    },\r\n    data() {\r\n        return {\r\n            state: {\r\n                disabledDates: {\r\n                    to: new Date(new Date().getTime() - 86400000),\r\n                    from: new Date(new Date().getTime() + (86400000 * 30))\r\n                }\r\n            },\r\n            start_date: '',\r\n            end_date: '',\r\n            jan: false,\r\n            feb: false,\r\n            mar: false,\r\n            apr: false,\r\n            may: false,\r\n            jun: false,\r\n            jul: false,\r\n            aug: false,\r\n            sep: false,\r\n            oct: false,\r\n            nov: false,\r\n            dec: false,\r\n            checked: false,\r\n            base_url: window.base_url,\r\n            api_url: window.api_url,\r\n            token: this.$localStorage.get(\"d_token\"),\r\n            items: [],\r\n            status: '',\r\n            updateForm: new Form({\r\n                items: '',\r\n            }),\r\n        };\r\n    },\r\n    created() {\r\n        this.getItems();\r\n    },\r\n    methods: {\r\n        check(month, value) {\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].setting[month] = value;\r\n            }\r\n            this.updatePermission(month, value, this.start_date, this.end_date, null);\r\n\r\n        },\r\n        updatePermission(month, value, start_date, end_date, dept_id) {\r\n            if (dept_id) {\r\n                this.updateForm.dept_id = dept_id;\r\n            }\r\n            console.log('end_date');\r\n            console.log(end_date);\r\n            console.log('end_date');\r\n            this.updateForm.month = month;\r\n            this.updateForm.month_value = value ? 1 : 0;\r\n\r\n            this.items.start_date = this.format_Date(start_date);\r\n            this.items.end_date = this.format_Date(end_date);\r\n\r\n            this.updateForm.post(this.api_url + \"all_dept_mos_permission_update\", {\r\n                headers: {\r\n                    \"Content-Type\": \"application/json\",\r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            }).then((res) => {\r\n                console.log(res);\r\n                if (res.data.success) {\r\n\r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                    });\r\n                }\r\n                loader.hide();\r\n                //this.$router.push('/department');\r\n            }, (error) => {\r\n                console.log(error);\r\n                loader.hide();\r\n            })\r\n        },\r\n        datepickerClosedFunction() {\r\n\r\n        },\r\n        startDateClosedFunction() {\r\n            console.log(this.start_date);\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].setting.start_date = this.start_date;\r\n            }\r\n\r\n            this.updateForm.items = this.items;\r\n            this.updateForm.post(this.api_url + \"department_mos_permission_settings_update\", {\r\n                headers: {\r\n                    \"Content-Type\": \"application/json\",\r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            }).then((res) => {\r\n                console.log(res);\r\n                if (res.data.success) {\r\n\r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                    });\r\n                }\r\n                loader.hide();\r\n                //this.$router.push('/department');\r\n            }, (error) => {\r\n                console.log(error);\r\n                loader.hide();\r\n            })\r\n\r\n        },\r\n        endDateClosedFunction() {\r\n            console.log(this.start_date);\r\n            for (let index = 0; index < this.items.length; index++) {\r\n                this.items[index].setting.end_date = this.end_date;\r\n            }\r\n        },\r\n        async statusChange(item, status) {\r\n            let editForm = new Form({\r\n                status: status,\r\n                name: item.name\r\n            })\r\n            try {\r\n                let loader = this.$loading.show();\r\n                editForm.put(this.api_url + \"departments/\" + item.id, {\r\n                    headers: {\r\n                        \"Content-Type\": \"application/json\",\r\n                        Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                }).then((res) => {\r\n                    console.log(res);\r\n                    if (res.data.success) {\r\n                        this.$toasted.show(res.data.message, {\r\n                            theme: \"bubble\",\r\n                            duration: 5000,\r\n                            position: \"bottom-right\",\r\n                        });\r\n                    }\r\n                    loader.hide();\r\n                    this.getItems();\r\n                }, (error) => {\r\n                    console.log(error);\r\n                    loader.hide();\r\n                })\r\n            } catch (error) {\r\n                // loader.hide(); \r\n                console.log(error);\r\n            }\r\n        },\r\n        update() {\r\n\r