     } catch (error) {\r\n                loader.hide();\r\n            }\r\n        },\r\n        async delete_row(id) {\r\n            console.log(id);\r\n            let loader = this.$loading.show();\r\n            try {\r\n                await axios\r\n                    .delete(this.api_url + \"users/\" + id, {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        res\r\n                    }) => {\r\n                        if (res.data.success) {\r\n                            this.$toasted.show(res.data.message, {\r\n                                theme: \"bubble\",\r\n                                duration: 5000,\r\n                                position: \"bottom-right\",\r\n                            });\r\n                        }\r\n                        loader.hide();\r\n                    });\r\n            } catch (error) {\r\n                loader.hide();\r\n            }\r\n        },\r\n        async getItems(designation_val,actv_status) {\r\n            let where = '?'; \r\n      \r\n            if (designation_val) {\r\n                where += '&designation=' + designation_val;\r\n            }\r\n\r\n            if (actv_status) {\r\n                where += '&actv_status=' + actv_status;\r\n            }            \r\n            let loader = this.$loading.show();\r\n\r\n            try {\r\n                await axios\r\n                    .get(this.api_url + \"tour_plan_users\" + where, {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        if (data.success) {\r\n                            this.items = data.data;\r\n                        }\r\n                        loader.hide();\r\n                    });\r\n            } catch (error) {\r\n                loader.hide();\r\n            }\r\n        },\r\n        async designations_fnctn(){\r\n            let where = '?';\r\n            let loader = this.$loading.show();\r\n            try {\r\n                await axios\r\n                    .get(this.api_url + \"tour_designation\" + where, {\r\n                    headers: {\r\n                        \"Content-Type\": \"application/json\",\r\n                        Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                    })\r\n                    .then(({\r\n                            data\r\n                        }) => {\r\n                    if (data.success) {\r\n                        this.users_data = data.data;\r\n                        let auth_user = JSON.parse(this.$localStorage.get(\"user\"));\r\n                        this.role = auth_user.role_id;\r\n                        this.designation_list = this.users_data.users;\r\n                        console.log('disation list',this.designation_list);\r\n                    }\r\n                    loader.hide();\r\n                    });\r\n            } catch (error) {\r\n                loader.hide();\r\n            }\r\n        },    \r\n    },\r\n    computed: {\r\n        filteredItems() {\r\n            return this.items.filter(item => {\r\n                return item.email.toLowerCase().indexOf(this.search.toLowerCase()) > -1\r\n            })\r\n        }\r\n    },\r\n};\r\n</script>\r\n","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules