div>\r\n                            </div>\r\n                            <div class=\"form-group\">\r\n                              <label>Division</label>\r\n                              <div class=\"form-group row\">\r\n                                <select class=\"form-control\" v-model=\"addForm.division_id\" id=\"users-list-verified\">\r\n                                  <option value=\"\">Select One</option>\r\n                                  <option v-for=\"row in division_list\" :key=\"row.id\" :value=\"row.id\">\r\n                                    {{ row.name }}\r\n                                  </option>\r\n                                </select>\r\n                              </div>\r\n                            </div>  \r\n                          </div>\r\n                        </div>\r\n                        <button type=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n                      </form>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n          <!-- Input Validation end -->\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n<script>\r\n//import axios from \"../../axios_instance\"; \r\nimport {Form} from \"vform\";\r\nimport axios from \"../../axios_instance\";\r\n\r\nexport default {\r\n  props: {},\r\n  components: {\r\n    // VueRecaptcha, facebookLogin \r\n  },\r\n  data() {\r\n    return {\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      DepartmentsItems: [],\r\n      users: [],\r\n      rsm: [],\r\n      adsm: [],\r\n      dsm: [],\r\n      asm: [],\r\n      sm: [],\r\n      divisional_head: [],\r\n      division_list: [],\r\n      hos: [],\r\n      businessTypes: [],\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      addForm: new Form({\r\n        name: \"\",\r\n        email: \"\",\r\n        dept_id: \"\",\r\n        password: \"\",\r\n        phone: \"\",\r\n        base_station_address: \"\",\r\n        role_id: 10,\r\n        wing_id: \"\",\r\n        employee_id: \"\",\r\n        designation: \"\",\r\n        tour_permission: 1,\r\n        la: \"1\",\r\n        rsm: \"\",\r\n        adsm: \"\",\r\n        dsm: \"\",\r\n        asm: \"\",\r\n        sm: \"\",\r\n        division_head: \"\",\r\n        division_id : \"\"\r\n\r\n      }),\r\n      roles: [],\r\n      WingsItems: [],\r\n    };\r\n  },\r\n  created() {\r\n    this.user();\r\n    this.getBusinessTypes();\r\n    this.division_fnctn();\r\n  },\r\n  methods: {\r\n    async division_fnctn(){\r\n            let where = '?';\r\n            let loader = this.$loading.show();\r\n            try {\r\n                await axios\r\n                    .get(this.api_url + \"divisions\" + where, {\r\n                    headers: {\r\n                        \"Content-Type\": \"application/json\",\r\n                        Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                    })\r\n                    .then(({\r\n                            data\r\n                        }) => {\r\n                    if (data.success) {\r\n                        this.division_list = data.data;\r\n                        \r\n                    }\r\n                    loader.hide();\r\n                    });\r\n            } catch (error) {\r\n                loader.hide();\r\n            }\r\n        },\r\n    //tour_users\r\n    async user() {\r\n      let where = '?';\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n            .get(this.api_url + \"tour_user\" + where, {\r\n              headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n              },\r\n            })\r\n            .then(({\r\n                     data\r\n                   }) => {\r\n     