 \"\"\r\n              },\r\n            })\r\n            .then(({data}) => {\r\n              if (data.success) {\r\n                this.itemDepartments = data.data\r\n              }\r\n              loader.hide();\r\n              //console.log(this.item);\r\n            });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n    async getRole() {\r\n      await axios.get(this.api_url + \"role\", {\r\n        headers: {\r\n          \"Content-Type\": \"application/json\",\r\n          Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n        },\r\n      })\r\n          .then(({data}) => {\r\n            this.roles = data.data;\r\n            //console.log(this.roles);\r\n          });\r\n    },\r\n    update() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n        this.editForm.put(this.api_url + \"users/\" + this.id, {\r\n          headers: {\r\n            \"Content-Type\": \"application/json\",\r\n            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n          },\r\n        }).then((res) => {\r\n          //console.log(res);\r\n          if (res.data.success) {\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n              duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          }\r\n          loader.hide();\r\n          this.$router.push('/tour_users');\r\n        }, (error) => {\r\n          console.log(error);\r\n          loader.hide();\r\n        })\r\n      } catch (error) {\r\n        // loader.hide();\r\n        //console.log(error);\r\n      }\r\n    }\r\n  },\r\n  computed: {},\r\n};\r\n</script>\r\n","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./t