n                        <button\r\n                          type=\"button\"\r\n                          class=\"\r\n                            btn btn-primary\r\n                            add-btn\r\n                            btn-lg\r\n                            d-flex\r\n                            align-items-center\r\n                          \"\r\n                          v-if=\"\r\n                            role_id == 1 ||\r\n                            role_id == 2 ||\r\n                            role_id == 3 ||\r\n                            role_id == 4 ||\r\n                            role_id == 8\r\n                          \"\r\n                        >\r\n                          <!--  DAILY NOT UPDATE BUTTON -->\r\n                          <router-link\r\n                            :to=\"{ path: '/daliy_not_update' }\"\r\n                            class=\"text-white\"\r\n                          >\r\n                            <i class=\"bx bx-add-alt\"> </i>\r\n                            Daily Not Update\r\n                          </router-link>\r\n                        </button>\r\n                      </div>\r\n\r\n                      <h3>Daily Works</h3>\r\n                      <br />\r\n                      <div class=\"table-responsive\">\r\n                        <table\r\n                          class=\"\r\n                            table\r\n                            table-bordered\r\n                            table-condensed\r\n                            table-hover\r\n                            table-striped\r\n                          \"\r\n                        >\r\n                          <thead class=\"thead-dark\">\r\n                            <tr>\r\n                              <th style=\"width: 15%\">Date</th>\r\n                              <!-- <th style=\"width: 5%\">Time</th> -->\r\n                              <th\r\n                                v-if=\"\r\n                                  role_id == 1 ||\r\n                                  role_id == 2 ||\r\n                                  role_id == 3 ||\r\n                                  role_id == 4 ||\r\n                                  role_id == 8\r\n                                \"\r\n                              >\r\n                                Dept.\r\n                              </th>\r\n                              <th v-if=\"searchValueTaypeVisible(0)\" style=\"width: 25%\">Things to Do</th>\r\n                              <template v-for=\"(schedule ,index) in scheduleTypes\" >\r\n                                <th style=\"width: 25%\" :key=\"index\" v-if=\"searchValueTaypeVisible(schedule.id)\" >\r\n                                  {{schedule.name}}\r\n                                </th>\r\n                              </template>\r\n                              \r\n                              <th\r\n                                style=\"width: 5%\"\r\n                                v-if=\"\r\n                                  filterForm.show_kra == 1 &&\r\n                                  (role_id == 5 || role_id == 6 || role_id == 7)\r\n                                \"\r\n                              >\r\n                                KRA\r\n                              </th>\r\n                              <th\r\n                                style=\"width: 5%\"\r\n                                v-if=\"\r\n                                  filterForm.show_kpi == 1 &&\r\n                                  (role_id == 5 || role_id == 6 || role_id == 7)\r\n                                \"\r\n                              >\r\n                                KPI\r\n                              </th>\r\n                              <th\r\n                                style=\"width: 5%\"\r\n                                v-if=\"\r\n                                  filterForm.show_mos == 1 &&\r\n                                  (role_id == 5 || role_id == 6 || role_id == 7)\r\n                                \"\r\n                              >\r\n                                MOS\r\n                              </th>\r\n                              <th style=\"width: 5%\">Comments</th>\r\n                              <th\r\n                                v-if=\"\r\n                                  role_id == 5 || role_id == 6 || role_id == 7 || role_id==3\r\n                                \"\r\n                              >\r\n                                Name\r\n                              </th>\r\n                              <th style=\"width: 5%\">Status</th>\r\n                              <th>Action</th>\r\n                            </tr>\r\n                          </thead>\r\n                          <tbody>\r\n                             \r\n                            <template v-for=\"(item, index) in items\">\r\n                              <tr\r\n                                :key=\"index\"\r\n                                v-if=\"\r\n                                  item.role_id == 1 ||\r\n                                  item.role_id == 2 ||\r\n                                  item.role_id == 3 ||\r\n                                  item.role_id == 4 ||\r\n                                  item.role_id == 5\r\n                                \"\r\n                                v-bind:class=\"[\r\n                                  item.status == 1 ? 'done' : 'not_done',\r\n                                ]\"\r\n                              >\r\n                                <td>\r\n                                  {{ format_Date(item.date) }}\r\n                                  <span class=\"date_time_start_end\">{{ formatAMPM(item.start_time) }} to {{ formatAMPM(item.end_time) }} </span>\r\n                                </td> \r\n                                <td\r\n                                  v-if=\"\r\n                                    role_id == 1 ||\r\n                                    role_id == 2 ||\r\n                                    role_id == 3 ||\r\n                                    role_id == 4 ||\r\n                                    role_id == 8\r\n                                  \"\r\n                                >\r\n                                  {{ item.deptjoin ? item.deptjoin.name : \"\" }}\r\n                                </td>\r\n                                <td v-if=\"searchValueTaypeVisible(0)\" > \r\n                                  <p\r\n                                    style=\"color: red; font-size: 16px\"\r\n                                    v-if=\"item.top_priority\"\r\n                                  >\r\n                                    <strong>\r\n                                      <u> Top priority </u>\r\n                                    </strong>\r\n                                  </p>\r\n                                  <strong v-if=\"item.factory_formatjoin\">\r\n                                    {{\r\n                                      item.factory_formatjoin\r\n                                        ? item.factory_formatjoin.headname\r\n                                        : \"\"\r\n                                    }}\r\n                                  </strong>\r\n                                  \r\n                                  <p v-html=\"item.task\"></p> \r\n\r\n                                </td>\r\n                                <template  v-for=\"(schedule ,index) in scheduleTypes\">\r\n                                  <td :key=\"index\" v-if=\"searchValueTaypeVisible(schedule.id)\" >\r\n                                    <div v-if=\"item.schedule_items.length > 0 \">\r\n                                      <div v-for=\"(row, index) in item.schedule_items\" :key=\"index\">\r\n                                        <div v-if=\"searchValueTaypeVisible(row.schedule_type_id) && (row.schedule_type_id == schedule.id) \"  > \r\n                                          <!-- <strong >{{row.name ? row.name: \"\"}}</strong>   -->\r\n                                          <p v-html=\"row.schedule_details\"></p>  \r\n                                        </div>\r\n                                      </div> \r\n                                    </div> \r\n                                  </td>\r\n\r\n                                </template>\r\n                                \r\n                                <td\r\n                                  v-if=\"\r\n                                    filterForm.show_kra == 1 &&\r\n                                    (role_id == 5 ||\r\n                                      role_id == 6 ||\r\n                                      role_id == 7)\r\n                                  \"\r\n                                >\r\n                                  {{\r\n                                    item.krajoin ? item.krajoin.kra_name : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <td\r\n                                  v-if=\"\r\n                                    filterForm.show_kpi == 1 &&\r\n                                    (role_id == 5 ||\r\n                                      role_id == 6 ||\r\n                                      role_id == 7)\r\n                                  \"\r\n                                >\r\n                                  {{\r\n                                    item.kpijoin ? item.kpijoin.kpi_name : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <td\r\n                                  v-if=\"\r\n                                    filterForm.show_mos == 1 &&\r\n                                    (role_id == 5 ||\r\n                                      role_id == 6 ||\r\n                                      role_id == 7)\r\n                                  \"\r\n                                >\r\n                                  {{\r\n                                    item.mosjoin ? item.mosjoin.mos_name : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <td>\r\n                                  <div\r\n                                    :key=\"index3\"\r\n                                    v-for=\"(com, index3) in item.comments\"\r\n                                  >\r\n                                    <i> @{{ com.user_name }} </i>\r\n                                    <br />\r\n                                    <p v-html=\"com.comment\"></p>\r\n                                    <br />\r\n                                  </div>\r\n                                </td>\r\n                                <td\r\n                                  v-if=\"\r\n                                    role_id == 5 || role_id == 6 || role_id == 7 || role_id==3\r\n                                  \"\r\n                                >\r\n                                  {{ item.userjoin ? item.userjoin.name : \"\" }}\r\n                                </td>\r\n                                <td>\r\n                                  <a\r\n                                    @click=\"statusChange(1, item)\"\r\n                                    v-if=\"item.status == 0\"\r\n                                  >\r\n                                    <img\r\n                                      :src=\"\r\n                                        base_url +\r\n                                        'assets/app-assets/images/logo/pen.png'\r\n                                      \"\r\n                                      class=\"logo_done\"\r\n                                      width=\"30px\"\r\n                                    />\r\n                                  </a