         getToDate() {\r\n                var date = new Date();\r\n                date.setDate(date.getDate() - 3);\r\n                var finalDate = date.getFullYear() + ', ' + (date.getMonth() + 1) + ', ' + date.getDate();\r\n                return finalDate; \r\n                //console.log('lastDate',finalDate);\r\n            },\r\n            async dailyScheduleTypes(){\r\n                await axios.get(this.api_url + \"daily_schedule_types\", {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.scheduleTypes = data.data;\r\n                        console.log(this.scheduleTypes);\r\n                    });\r\n            },\r\n            scheduleTypesName(id){  \r\n                for (let index = 0; index < this.scheduleTypes.length; index++) { \r\n                    if(this.scheduleTypes[index].id == id){\r\n                        return this.scheduleTypes[index].name ; \r\n                    }\r\n                }\r\n            },\r\n            item_add(){\r\n \r\n                let newItem = {\r\n                        schedule_type_id : \"\"  ,\r\n                        schedule_details : \"\"\r\n                    }; \r\n                this.addForm.othersSchedules.push(newItem);\r\n            },\r\n            item_removes(id){\r\n                console.log(id);\r\n                //alert(id); \r\n                //this.addForm.othersSchedules\r\n                this.$swal({\r\n                    title: \"Are you sure?\",\r\n                    text: \"Once deleted, you will not be able to recover this item!\",\r\n                    icon: \"warning\",\r\n                    buttons: true,\r\n                    dangerMode: true,\r\n                    })\r\n                    .then((willDelete) => {\r\n                        if (willDelete) { \r\n                            this.addForm.othersSchedules.splice(id, 1);\r\n                            // this.$swal(\"Your item has been deleted!\", {\r\n                            // icon: \"success\",\r\n                            // });\r\n                        }  \r\n                    });\r\n            },\r\n\r\n            getFromDate() {\r\n                var date = new Date();\r\n                date.setDate(date.getDate() + 1);\r\n                var finalDate = date.getFullYear() + ', ' + (date.getMonth() + 1) + ', ' + date.getDate();\r\n                return finalDate;\r\n\r\n                //console.log('lastDate',finalDate);\r\n            },\r\n\r\n\r\n            onUpdate({\r\n                getJSON,\r\n                getHTML\r\n            }) {\r\n                this.json = getJSON()\r\n                this.html = getHTML()\r\n                console.log('html', this.html)\r\n            },\r\n            create() {\r\n                try {\r\n                    let loader = this.$loading.show();\r\n                    // this.addForm.task = this.$refs.editor.getContent();\r\n                    this.addForm.post(this.api_url + \"daily_schedules\", {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    }).then((res) => {\r\n                        console.log(res);\r\n                        console.log(console.log(res.headers));\r\n                        if (res.data.success) {\r\n                            this.$toasted.show(res.data.message, {\r\n                                theme: \"bubble\",\r\n                                duration: 5000,\r\n                                position: \"bottom-right\",\r\n                            });\r\n                        }\r\n                        loader.hide();\r\n                        this.$router.push('/task');\r\n                    }, (error) => {\r\n                        console.log(error);\r\n                        loader.hide();\r\n                    })\r\n                } catch (error) {\r\n                    // loader.hide(); \r\n                    console.log(error);\r\n                }\r\n            },\r\n            async dept() {\r\n                this.getDepartments().then(({\r\n                    data\r\n                }) => {\r\n                    if (data.success) {\r\n                        this.DepartmentsItems = data.data;\r\n                    }\r\n                });\r\n            },\r\n\r\n            async getKRA() {\r\n\r\n                await axios.get(this.api_url + \"k_r_a_s?year=\" + this.year, {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.kraItem = data.data;\r\n                    });\r\n            },\r\n            async getKpi() {\r\n                console.log(this.addForm.kra_id);\r\n                await axios.get(this.api_url + \"k_p_i_s?kra_id=\" + this.addForm.kra_id, {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.kpiItem = data.data;\r\n                        console.log(this.roles);\r\n                    });\r\n            },\r\n            async getMos() {\r\n                await axios.get(this.api_url + \"m_o_s?kpi_id=\" + this.addForm.kpi_id, {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.mosItem = data.data;\r\n                        console.log(this.roles);\r\n                    });\r\n            },\r\n            async getRole() {\r\n                await axios.get(this.api_url + \"role\", {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.roles = data.data;\r\n                        console.log(this.roles);\r\n                    });\r\n            },\r\n        },\r\n        computed: {},\r\n    };\r\n</script>\r\n<style>\r\n\r\n</style>","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./add_daily_work.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader