epicker :disabled-dates=\"state.disabledDates\" @closed=\"datepickerClosedFunction\"\r\n                      class=\"form-control\" name=\"date\" v-model=\"filterForm.date\">\r\n                    </datepicker>\r\n                  </fieldset>\r\n                </div>\r\n\r\n                <!-- TO DATE  -->\r\n                <div class=\"col-12 col-sm-6 col-lg-2\" v-if=\"filterForm.dateRange == true\">\r\n                  <label class=\"control-label\"> TO Date </label>\r\n                  <fieldset class=\"form-group\">\r\n                    <datepicker :disabled-dates=\"state.disabledDates\" @closed=\"datepickerClosedFunction\"\r\n                      class=\"form-control\" name=\"toDate\" v-model=\"filterForm.toDate\">\r\n                    </datepicker>\r\n                  </fieldset>\r\n                </div>\r\n\r\n                <div class=\"col-12 col-sm-6 col-lg-2\">\r\n                  <label class=\"control-label\"> With Date Range </label>\r\n                  <fieldset class=\"form-group\">\r\n                    <input type=\"checkbox\" class=\"from-control\" @click=\"datepickerClosedFunction\" name=\"dateRange\"\r\n                      v-model=\"filterForm.dateRange\" />\r\n\r\n                  </fieldset>\r\n                </div>\r\n\r\n                <div class=\"col-12 col-sm-6 col-lg-2\" v-if=\"deptInfo.template_setting == 2 || user_data.id == 24\">\r\n                  <label class=\"control-label\">Old Format</label>\r\n                  <fieldset class=\"form-group\">\r\n                    <input type=\"checkbox\" class=\"from-control\" @click=\"closedFunction\" name=\"old_format\"\r\n                      v-model=\"filterForm.old_format\" value=\"1\" />\r\n                  </fieldset>\r\n                </div>\r\n              </div>\r\n              <div class=\"row\" v-if=\"(deptInfo.template_setting == 2 || user_data.id == 24) && !filterForm.old_format\">\r\n                <div class=\"col-12 col-sm-6 col-lg-2\" v-for=\"