                                             </a>\r\n                                                    <a @click=\"taskStatusChange(index, index2, 0, row)\"\r\n                                                      v-if=\"row.status == 1\">\r\n                                                      <img :src=\"\r\n                                                        base_url +\r\n                                                        'assets/app-assets/images/logo/done.png'\r\n                                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                                    </a>\r\n                                                  </td>\r\n                                                </tr>\r\n                                              </template>\r\n                                            </tbody>\r\n                                          </table>\r\n                                        </div>\r\n                                      </td>\r\n                                    </template>\r\n                                  </template>\r\n                                  <td v-if=\"searchValueTaype.length == 0\">\r\n                                    <div class=\"task_status\" v-if=\"item.task\">\r\n                                      <a @click=\"statusChange(1, item)\" v-if=\"item.status == 0\">\r\n                                        <img :src=\"\r\n                                          base_url +\r\n                                          'assets/app-assets/images/logo/pen.png'\r\n                                        \" class=\"logo_done\" width=\"30px\" />\r\n                                      </a>\r\n                                      <a @click=\"statusChange(0, item)\" v-if=\"item.status == 1\">\r\n                                        <img :src=\"\r\n                                          base_url +\r\n                                          'assets/app-assets/images/logo/done.png'\r\n                                        \" class=\"logo_done\" width=\"30px\" />\r\n                                      </a>\r\n                                    </div>\r\n                                    <p style=\"color: red; font-size: 16px\" v-if=\"item.top_priority\">\r\n                                      <strong>\r\n                                        <u> Top priority </u>\r\n                                      </strong>\r\n                                    </p>\r\n                                    <strong v-if=\"item.factory_formatjoin\">\r\n                                      {{\r\n                                          item.factory_formatjoin\r\n                                            ? item.factory_formatjoin.headname\r\n                                            : \"\"\r\n                                      }}\r\n                                    </strong>\r\n\r\n                                    <p style=\"font-size: 15px\" v-html=\"item.task\"></p>\r\n                                    <div v-if=\"item.tasks.length > 0 && filterForm.old_format\">\r\n                                      <table class=\"\r\n                                      table\r\n                                      table-bordered\r\n                                      table-condensed\r\n                                      table-hover\r\n                                      table-striped\r\n                                    \">\r\n                                        <tbody>\r\n                                          <template v-for=\"(row, index2) in item.tasks\">\r\n                                            <template v-if=\"searchValueTaypeVisible(row.schedule_type_id)\">\r\n                                              <tr :key=\"index2\">\r\n\r\n                                                <td>\r\n                                                  <div class=\"task_status\" v-if=\"filterForm.report_viwe == false\">\r\n                                                    <a @click=\"taskStatusChange(index, index2, 1, row)\"\r\n                                                      v-if=\"row.status == 0\">\r\n                                                      <img :src=\"\r\n                                                        base_url +\r\n                                                        'assets/app-assets/images/logo/pen.png'\r\n                                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                                    </a>\r\n                                                    <a @click=\"taskStatusChange(index, index2, 0, row)\"\r\n                                                      v-if=\"row.status == 1\">\r\n                                                      <img :src=\"\r\n                                                        base_url +\r\n                                                        'assets/app-assets/images/logo/done.png'\r\n                                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                                    </a>\r\n                                                  </div>\r\n\r\n                                                  <p style=\"color: red; font-size: 16px\" v-if=\"row.top_priority\">\r\n                                                    <strong>\r\n                                                      <u> Top priority </u>\r\n                                                    </strong>\r\n                                                  </p>\r\n\r\n                                                  <b>{{ functionName(row.schedule_type_id) }}</b><br>\r\n                                                  <p style=\"font-size: 15px\"\r\n                                                    v-html=\"row.task.replace(/(?:\\r\\n|\\r|\\n)/g, '<br />')\"></p>\r\n                                                  <p class=\"start-to-end-time\"\r\n                                                    v-if=\"row.start_time && row.start_time.length < 11\">\r\n                                                    {{ row.start_time }} - {{ row.end_time }}</p>\r\n\r\n                                                </td>\r\n\r\n                                              </tr>\r\n                                            </template>\r\n                                          </template>\r\n                                        </tbody>\r\n                                      </table>\r\n                                    </div>\r\n\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.report_viwe == false\">\r\n                                    <div :key=\"index3\" v-for=\"(com, index3) in item.comments\">\r\n                                      <i> @{{ com.user_name }} </i>\r\n                                      <br />\r\n                                      <p v-html=\"com.comment\"></p>\r\n                                      <br />\r\n                                    </div>\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.report_viwe == false\">\r\n                                    <div class=\"dropup\">\r\n\r\n                                      <span aria-expanded=\"false\" aria-haspopup=\"true\" class=\"\r\n                                        bx bx-dots-vertical-rounded\r\n                                        font-medium-3\r\n                                        dropdown-toggle\r\n                                        nav-hide-arrow\r\n                                        cursor-pointer\r\n                                      \" data-toggle=\"dropdown\" role=\"menu\">\r\n                                      </span>\r\n                                      <div class=\"dropdown-menu dropdown-menu-right\">\r\n\r\n\r\n\r\n                                        <router-link\r\n                                          v-if=\"(format_Date(item.date) == currentDate) && deptInfo.template_setting == 2 && (role_id == 3 || role_id == 5)\"\r\n                                          :to=\"{ path: '/edit_task/' + item.id }\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                          edit\r\n                                        </router-link>\r\n\r\n                                        <router-link\r\n                                          v-if=\"(format_Date(item.date) == currentDate) && deptInfo.template_setting == 1 || (role_id == 6 || role_id == 7 || role_id == 10 || user_data.id == 24)\"\r\n                                          :to=\"{\r\n                                            path: '/edit_daily_work/' + item.id,\r\n                                          }\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                          edit\r\n                                        </router-link>\r\n\r\n                                        <a @click=\"comment_show(item)\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-comment mr-1\"> </i>\r\n                                          Comment\r\n                                        </a>\r\n\r\n                                        <a @click=\"delete_row(item.id)\" v-if=\"item.status == 0\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-trash mr-1\"> </i>\r\n                                          Delete\r\n                                        </a>\r\n                                      </div>\r\n                                    </div>\r\n                                  </td>\r\n                                </tr>\r\n                              </template>\r\n                            </template>\r\n\r\n                          </tbody>\r\n                        </table>\r\n                        <table v-if=\"(role_id == 5 || role_id == 6 || role_id == 7 || role_id == 10)\" class=\"\r\n                            table\r\n                            table-bordered\r\n                            table-condensed\r\n                            table-hover\r\n                            table-striped\r\n                          \">\r\n                          <thead class=\"thead-dark\">\r\n                            <tr>\r\n                              <th>Date</th>\r\n                              <th>Things to Do</th>\r\n                              <th>Name</th>\r\n                              <th style=\"width: 5%\">Comments</th>\r\n                              <th>Status</th>\r\n                              <th>Action</th>\r\n                            </tr>\r\n                          </thead>\r\n                          <tbody>\r\n                            <tr v-if=\"role_id == 5\">\r\n                              <th colspan=\"6\">Wings</th>\r\n                            </tr>\r\n                            <template v-for=\"(item, index) in items\">\r\n                              <template v-if=\"item.role_id == 6\">\r\n                                <tr :key=\"index\" v-bind:class=\"[\r\n                                  item.status == 1 ? 'done' : 'not_done',\r\n                                ]\">\r\n                                  <td>\r\n                                    {{ format_Date(item.date) }}\r\n                                    <p class=\"start-to-end-time\">{{ item.start_time }} - {{ item.end_time }}</p>\r\n                                  </td>\r\n                                  <td v-if=\"\r\n                                    role_id == 1 ||\r\n                                    role_id == 2 ||\r\n                                    role_id == 3 ||\r\n                                    role_id == 4 ||\r\n                                    role_id == 8\r\n                                  \">\r\n                                    {{ item.userjoin ? item.userjoin.name : \"\" }}( {{ item.deptjoin ? item.deptjoin.name\r\n                                        : \"\"\r\n                                    }})\r\n\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.things_to_do\">\r\n                                    <p style=\"color: red; font-size: 16px\" v-if=\"item.top_priority\">\r\n                                      <strong>\r\n                                        <u> Top priority </u>\r\n                                      </strong>\r\n                                    </p>\r\n                                    <strong v-if=\"item.factory_formatjoin\">\r\n                                      {{\r\n                                          item.factory_formatjoin\r\n                                            ? item.factory_formatjoin.headname\r\n                                            : \"\"\r\n                                      }}\r\n                                    </strong>\r\n\r\n                                    <p v-html=\"item.task\"></p>\r\n                                  </td>\r\n                                  <td> {{ item.userjoin ? item.userjoin.name : \"\" }}</td>\r\n                                  <td>\r\n                                    <div :key=\"index3\" v-for=\"(com, index3) in item.comments\">\r\n                                      <i> @{{ com.user_name }} </i>\r\n                                      <br />\r\n                                      <p v-html=\"com.comment\"></p>\r\n                                      <br />\r\n                                    </div>\r\n                                  </td>\r\n                                  <td>\r\n                                    <a @click=\"statusChange(1, item)\" v-if=\"item.status == 0\">\r\n                                      <img :src=\"\r\n                                        base_url +\r\n                                        'assets/app-assets/images/logo/pen.png'\r\n                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                    </a>\r\n                                    <a @click=\"statusChange(0, item)\" v-if=\"item.status == 1\">\r\n                                      <img :src=\"\r\n                                        base_url +\r\n                                        'assets/app-assets/images/logo/done.png'\r\n                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                    </a>\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.report_viwe == false\">\r\n                                    <div class=\"dropup\">\r\n\r\n                                      <span aria-expanded=\"false\" aria-haspopup=\"true\" class=\"\r\n                                      bx bx-dots-vertical-rounded\r\n                                      font-medium-3\r\n                                      dropdown-toggle\r\n                                      nav-hide-arrow\r\n                                      cursor-pointer\r\n                                    \" data-toggle=\"dropdown\" role=\"menu\">\r\n                                      </span>\r\n                                      <div class=\"dropdown-menu dropdown-menu-right\">\r\n\r\n                                        <router-link v-if=\"format_Date(item.date) == currentDate\" :to=\"{\r\n                                          path: '/edit_daily_work/' + item.id,\r\n                                        }\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                          edit\r\n                                        </router-link>\r\n                                        <a @click=\"comment_show(item)\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-comment mr-1\"> </i>\r\n                                          Comment\r\n                                        </a>\r\n\r\n                                        <a @click=\"delete_row(item.id)\" v-if=\"item.status == 0\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-trash mr-1\"> </i>\r\n                                          Delete\r\n                                        </a>\r\n                                      </div>\r\n                                    </div>\r\n                                  </td>\r\n                                </tr>\r\n                              </template>\r\n                            </template>\r\n                            <tr v-if=\"role_id == 5 || role_id == 6\">\r\n                              <th colspan=\"6\">Employee</th>\r\n                            </tr>\r\n                            <template v-for=\"(item, index) in items\">\r\n                              <template v-if=\"item.role_id == 7 || item.role_id == 10\">\r\n                                <tr :key=\"index\" v-bind:class=\"[\r\n                                  item.status == 1 ? 'done' : 'not_done',\r\n                                ]\">\r\n                                  <td>\r\n                                    {{ format_Date(item.date) }}\r\n                                    <p class=\"start-to-end-time\">{{ item.start_time }} - {{ item.end_time }}</p>\r\n                                  </td>\r\n                                  <td v-if=\"\r\n                                    role_id == 1 ||\r\n                                    role_id == 2 ||\r\n                                    role_id == 3 ||\r\n                                    role_id == 4 ||\r\n                                    role_id == 8\r\n                                  \">\r\n                                    {{ item.userjoin ? item.userjoin.name : \"\" }}( {{ item.deptjoin ? item.deptjoin.name\r\n                                        : \"\"\r\n                                    }})\r\n\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.things_to_do\">\r\n                                    <p style=\"color: red; font-size: 16px\" v-if=\"item.top_priority\">\r\n                                      <strong>\r\n                                        <u> Top priority </u>\r\n                                      </strong>\r\n                                    </p>\r\n                                    <strong v-if=\"item.factory_formatjoin\">\r\n                                      {{\r\n                                          item.factory_formatjoin\r\n                                            ? item.factory_formatjoin.headname\r\n                                            : \"\"\r\n                                      }}\r\n                                    </strong>\r\n\r\n                                    <p v-html=\"item.task\"></p>\r\n                                  </td>\r\n                                  <td> {{ item.userjoin ? item.userjoin.name : \"\" }}</td>\r\n                                  <td>\r\n                                    <div :key=\"index3\" v-for=\"(com, index3) in item.comments\">\r\n                                      <i> @{{ com.user_name }} </i>\r\n                                      <br />\r\n                                      <p v-html=\"com.comment\"></p>\r\n                                      <br />\r\n                                    </div>\r\n                                  </td>\r\n                                  <td>\r\n                                    <a @click=\"statusChange(1, item)\" v-if=\"item.status == 0\">\r\n                                      <img :src=\"\r\n                                        base_url +\r\n                                        'assets/app-assets/images/logo/pen.png'\r\n                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                    </a>\r\n                                    <a @click=\"statusChange(0, item)\" v-if=\"item.status == 1\">\r\n                                      <img :src=\"\r\n                                        base_url +\r\n                                        'assets/app-assets/images/logo/done.png'\r\n                                      \" class=\"logo_done\" width=\"30px\" />\r\n                                    </a>\r\n                                  </td>\r\n                                  <td v-if=\"filterForm.report_viwe == false\">\r\n                                    <div class=\"dropup\">\r\n\r\n                                      <span aria-expanded=\"false\" aria-haspopup=\"true\" class=\"\r\n                                      bx bx-dots-vertical-rounded\r\n                                      font-medium-3\r\n                                      dropdown-toggle\r\n                                      nav-hide-arrow\r\n                                      cursor-pointer\r\n                                    \" data-toggle=\"dropdown\" role=\"menu\">\r\n                                      </span>\r\n                                      <div class=\"dropdown-menu dropdown-menu-right\">\r\n\r\n                                        <router-link v-if=\"format_Date(item.date) == currentDate\" :to=\"{\r\n                                          path: '/edit_daily_work/' + item.id,\r\n                                        }\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                          edit\r\n                                        </router-link>\r\n                                        <a @click=\"comment_show(item)\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-comment mr-1\"> </i>\r\n                                          Comment\r\n                                        </a>\r\n\r\n                                        <a @click=\"delete_row(item.id)\" v-if=\"item.status == 0\" class=\"dropdown-item\">\r\n                                          <i class=\"bx bx-trash mr-1\"> </i>\r\n                                          Delete\r\n                                        </a>\r\n                                      </div>\r\n                                    </div>\r\n                                  </td>\r\n                                </tr>\r\n                              </template>\r\n                            </template>\r\n\r\n                          </tbody>\r\n                        </table>\r\n                      </div>\r\n                      <br />\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <modal height=\"80%\" name=\"comment\" style=\"padding: 50px\" width=\"65%\">\r\n      <i @click=\"comment_hidden()\" class=\"bx bx-x-circle x-circle\"> </i>\r\n      <div class=\"app-content\">\r\n        <div class=\"card\">\r\n          <section id=\"dashboard-analytics\">\r\n            <nav>\r\n              <div class=\"nav nav-tabs\" id=\"nav-tab\" role=\"tablist\">\r\n                <a @click=\"tabs('comments')\" aria-controls=\"nav-home\" aria-selected=\"true\" class=\"nav-item nav-link\"\r\n                  data-toggle=\"tab\" href=\"#nav-home\" id=\"nav-home-tab\" role=\"tab\"\r\n                  v-bind:class=\"{ active: comment_active == 'comments' }\">\r\n                  Comments\r\n                </a>\r\n                <a @click=\"tabs('add')\" aria-controls=\"nav-home\" aria-selected=\"true\" class=\"nav-item nav-link\"\r\n                  data-toggle=\"tab\" href=\"#nav-home\" id=\"nav-home-tab\" role=\"tab\"\r\n                  v-bind:class=\"{ active: comment_active == 'add' }\">\r\n                  New Comment\r\n                </a>\r\n              </div>\r\n            </nav>\r\n          </section>\r\n          <form @submit.prevent=\"task_comment()\">\r\n            <table class=\"table table-bordered table-striped table-sm\">\r\n              <tbody v-if=\"comment_active == 'add'\">\r\n                <tr>\r\n                  <th class=\"text-center\" colspan=\"4\">\r\n                    <vue-editor name=\"task\" placeholder=\"Comment....\" v-model=\"comment_mailForm.comment\">\r\n                    </vue-editor>\r\n                  </th>\r\n                </tr>\r\n                <tr>\r\n                  <th class=\"text-center\">\r\n                    <div class=\"form-group\">\r\n                      <label for=\"Profession\"> Mail CC1 </label>\r\n                      <div class=\"controls\">\r\n                        <input class=\"form-control\" placeholder=\"example1@gmail.com\" type=\"text\"\r\n                          v-model=\"comment_mailForm.mailcc1\" />\r\n                      </div>\r\n                    </div>\r\n                  </th>\r\n                  <th class=\"text-center\">\r\n                    <div class=\"form-group\">\r\n                      <label for=\"Profession\"> Mail CC3 </label>\r\n                      <div class=\"controls\">\r\n                        <input class=\"form-control\" placeholder=\"example2@gmail.com\" type=\"text\"\r\n                          v-model=\"comment_mailForm.mailcc2\" />\r\n                      </div>\r\n                    </div>\r\n                  </th>\r\n                  <th class=\"text-center\">\r\n                    <div class=\"form-group\">\r\n                      <label for=\"Profession\"> Mail CC3 </label>\r\n                      <div class=\"controls\">\r\n                        <input class=\"form-control\" placeholder=\"example3@gmail.com\" type=\"text\"\r\n                          v-model=\"comment_mailForm.mailcc3\" />\r\n                      </div>\r\n                    </div>\r\n                  </th>\r\n                  <th class=\"text-center\">\r\n                    <button class=\"btn btn-success\">Save</button>\r\n                  </th>\r\n                </tr>\r\n              </tbody>\r\n              <tbody v-if=\"comment_active == 'comments'\">\r\n                <tr class=\"text-center\">\r\n                  <th>Comment</th>\r\n                  <th>User Name</th>\r\n                  <th>Date</th>\r\n                </tr>\r\n                <tr :key=\"index\" class=\"text-center\" v-for=\"(com, index) in item.comments\">\r\n                  <th>\r\n                    <p v-html=\"com.comment\"></p>\r\n                  </th>\r\n                  <th>\r\n                    {{ com.user_name }}\r\n                  </th>\r\n                  <th>\r\n                    {{ format_Date(com.created_at) }}\r\n                  </th>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </form>\r\n        </div>\r\n      </div>\r\n    </modal>\r\n  </div>\r\n</template>\r\n<script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\";\r\nimport Select2 from 'v-select2-component';\r\nimport Datepicker from \"vuejs-datepicker\";\r\nimport { VueEditor } from \"vue2-editor\";\r\nexport default {\r\n  props: {},\r\n  components: {\r\n    Datepicker,\r\n    VueEditor,\r\n    'Select2': Select2,\r\n  },\r\n  data() {\r\n    return {\r\n      columns: [\r\n        {\r\n          label: \"Task\",\r\n          field: \"task\",\r\n          dataFormat: this.taskData,\r\n          rowspan: 4,\r\n        },\r\n        {\r\n          label: \"Date\",\r\n          field: \"date\",\r\n          dataFormat: this.taskDate,\r\n          rowspan: 4,\r\n        },\r\n        {\r\n          label: \"Name\",\r\n          field: \"userjoin.name\",\r\n          rowspan: 4,\r\n        }\r\n      ],\r\n      dataItemExel: [],\r\n\r\n\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n      role_id: \"\",\r\n      items: [],\r\n      item: [],\r\n      deptItems: [],\r\n      status: \"\",\r\n      scheduleTypes: [],\r\n      scheduleTypes_allow: false,\r\n      searchValueTaype: [],\r\n      deptInfo: [],\r\n      comment_active: \"comments\",\r\n      filterForm: new Form({\r\n        schedule: [],\r\n        dept_id: \"\",\r\n        things_to_do: true,\r\n        report_viwe: false,\r\n        dateRange: false,\r\n        date: new Date(),\r\n        toDate: new Date(),\r\n        wing_id: \"\",\r\n        user_id: \"\",\r\n        old_format: false\r\n      }),\r\n      comment_mailForm: new Form({\r\n        mailcc1: \"\",\r\n        mailcc2: \"\",\r\n        mailcc3: \"\",\r\n        comment: \"\",\r\n        daily_schedule_id: \"\",\r\n      }),\r\n      statusForm: new Form({}),\r\n      state: {\r\n        disabledDates: {\r\n          to: new Date(2020, 0, 0), // Disable all dates up to specific date\r\n          from: new Date(2030, 0, 0), // Disable all dates after specific date\r\n        },\r\n      },\r\n      currentDate: \"\",\r\n    };\r\n  },\r\n  created() {\r\n    this.role_id = this.user_data.role_id;\r\n    this.dept_id = this.user_data.dept_id;\r\n    this.getItems();\r\n    this.getDept();\r\n    this.getMydeptInfo(this.dept_id);\r\n    if (this.user_data.id == 24) {\r\n      this.filterForm.old_format = true;\r\n      this.dailyScheduleTypes();\r\n    }\r\n    let today = new Date();\r\n    let m;\r\n    m = today.getMonth() + 1;\r\n    if (m < 10) {\r\n      m = '0' + m;\r\n    }\r\n    let d;\r\n    d = today.getDate();\r\n    if (d < 10) {\r\n      d = '0' + d;\r\n    }\r\n\r\n    this.currentDate = today.getFullYear() + \"-\" + m + \"-\" + d;\r\n\r\n  },\r\n  methods: {\r\n\r\n    taskData(value) {\r\n      return value.replace(/<\\/?[^>]+>/ig, \" \");\r\n    },\r\n    taskDate(value) {\r\n      return this.format_Date(value);\r\n    },\r\n\r\n    checkTypes(e, typeId) {\r\n      if (e.target.checked) {\r\n        this.searchValueTaype.push(typeId);\r\n      } else {\r\n        for (let index = 0; index < this.searchValueTaype.length; index++) {\r\n          if (this.searchValueTaype[index] == typeId) {\r\n            this.searchValueTaype.splice(index, 1);\r\n          }\r\n        }\r\n      }\r\n      this.getItems();\r\n\r\n    },\r\n\r\n    tabs(i) {\r\n      this.comment_active = i;\r\n    },\r\n    comment_hidden() {\r\n      this.$modal.hide(\"comment\");\r\n    },\r\n    task_comment() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n        this.comment_mailForm.daily_schedule_id = this.item.id;\r\n        this.comment_mailForm\r\n          .post(this.api_url + \"daily_schedule_comments\", {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(\r\n            (res) => {\r\n              if (res.data.success) {\r\n                this.comment_hidden();\r\n                this.$toasted.show(res.data.message, {\r\n                  theme: \"bubble\",\r\n                  duration: 5000,\r\n                  position: \"bottom-right\",\r\n                });\r\n              }\r\n              loader.hide();\r\n            },\r\n            (error) => {\r\n              loader.hide();\r\n            }\r\n          );\r\n      } catch (error) {\r\n      }\r\n    },\r\n    checkDatacheck(role_id) {\r\n      let return_typr = true;\r\n      this.items.filter((item) => {\r\n        if (item.rol