\r\n                    <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                            <div class=\"card\">\r\n                                <div class=\"card-header\">\r\n                                    <h4 class=\"card-title\">Edit daily work</h4>\r\n                                </div>\r\n                                <div class=\"card-content\">\r\n                                    <div class=\"card-body\">\r\n                                        <form @submit.prevent=\"create()\">\r\n                                                <div class=\"row\"> \r\n                                                    <div class=\"col-md-3\"> \r\n                                                        <div class=\"form-group\">\r\n                                                            <label for=\"Profession\">Date</label>\r\n                                                            <div class=\"controls\">\r\n                                                                <datepicker v-model=\"editForm.date\" name=\"date\" class=\"form-control\"  ></datepicker>\r\n                                                                <!-- <input type=\"text\" name=\"date\" v-model=\"editForm.date\" :class=\"{  'is-invalid': editForm.errors.has('date'),  }\" class=\"form-control\" data-validation-required-message=\"This field is required\" placeholder=\"Date\"> -->\r\n                                                            </div>\r\n                                                        </div> \r\n                                                    </div>   \r\n                                                    <div class=\"col-md-3\"> \r\n                                                        <div class=\"form-group\">\r\n                                                            <label for=\"Profession\">KRA</label>\r\n                                                            <div class=\"controls\">\r\n                                                                <select  id=\"Profession\" name=\"kra_id\"  @change=\"getKpi()\"  v-model=\"editForm.kra_id\" :class=\"{  'is-invalid': editForm.errors.has('kra_id'),  }\" class=\"form-control\">\r\n                                                                    <option value=\"\">Select one</option>\r\n                                                                    <option  v-for=\"row in kraItem\" :key=\"row.id\" :value=\"row.id\">{{ row.kra_name}}</option>  \r\n                                                                </select>\r\n                                                            </div>\r\n                                                        </div> \r\n                                                    </div> \r\n                                                    <div class=\"col-md-3\"> \r\n                                                        <div class=\"form-group\">\r\n                                                            <label for=\"Profession\">KPI</label>\r\n                                                            <div class=\"controls\">\r\n                                                                <select  id=\"Profession\" name=\"kpi_id\" @change=\"getMos()\"   v-model=\"editForm.kpi_id\" :class=\"{  'is-invalid': editForm.errors.has('kpi_id'),  }\" class=\"form-control\">\r\n                                                                    <option value=\"\">Select one</option>\r\n                                                                    <option  v-for=\"row in kpiItem\" :key=\"row.id\" :value=\"row.id\">{{ row.kpi_name}}</option>  \r\n                                                                </select>\r\n                                                            </div>\r\n                                                        </div> \r\n                                                    </div> \r\n                                                    <div class=\"col-md-3\"> \r\n                                                        <div class=\"form-group\">\r\n                                                            <label for=\"Profession\">MOS</label>\r\n                                                            <div class=\"controls\">\r\n                                                                <select  id=\"Profession\" name=\"mos_id\"    v-model=\"editForm.mos_id\" :class=\"{  'is-invalid': editForm.errors.has('mos_id'),  }\" class=\"form-control\">\r\n                                                                    <option value=\"\">Select one</option>\r\n                                                                    <option  v-for=\"row in mosItem\" :key=\"row.id\" :value=\"row.id\">{{ row.mos_name}}</option>  \r\n                                                                </select>\r\n                                                            </div>\r\n                                                        </div> \r\n                                                    </div> \r\n\r\n\r\n                                                    <table class=\"table table-bordered table-sm\">\r\n                                                        <thead class=\"thead-dark\">\r\n                                                            <tr>\r\n                                                                <th style=\"width: 4px;\">No</th>\r\n                                                                <th>Work Details </th> \r\n                                                                <th style=\"width: 130px;\">Working Type</th>\r\n                                                                <th style=\"width: 20px;\">Start Time</th>  \r\n                                                                <th style=\"width: 20px;\">End Time</th> \r\n                                                                <th style=\"width: 20px;\">Working Time</th>\r\n                                                                <th style=\"width: 100px;\">Top Priority</th>\r\n                                                                <th style=\"width: 80px;\">Action</th>\r\n                                                            </tr>\r\n                                                        </thead>\r\n                                                        <tbody>\r\n                                                            \r\n                                                            <template v-for=\"(schedule ,index) in editForm.tasks\" >\r\n                                                                <tr :key=\"index\">\r\n                                                                    <td>{{ index+1 }}</td>\r\n                                                                    <td> \r\n                                                                        <textarea rows=\"1\" v-model=\"editForm.tasks[index].task\" class=\"form-control\" ></textarea>\r\n                                                                        <!-- <input placeholder=\"Work task\" style=\"width: 100%;\" type=\"text\" value=\"\"\r\n                                                                            v-model=\"editForm.tasks[index].schedule_details\" /> -->\r\n                                                                    </td> \r\n                                                                    <td>\r\n                                                                        <select id=\"Profession\" name=\"mos_id\"\r\n                                                                            v-model=\"editForm.tasks[index].schedule_type_id\"\r\n                                                                            :class=\"{  'is-invalid': editForm.errors.has('mos_id'),  }\"\r\n                                                                            class=\"form-control\">\r\n                                                                            <option value=\"\">Select one</option>\r\n                                                                            <option v-for=\"row in scheduleTypes\" :key=\"row.id\"\r\n                                                                                :value=\"row.id\">{{ row.name}}</option>\r\n                                                                        </select>\r\n                                                                    </td>\r\n                                                                    <td> \r\n                                                                        <vue-timepicker format=\"hh:mm a\" close-on-complete manual-input  v-model=\"editForm.tasks[index].start_time\" :minute-interval=\"15\"></vue-timepicker> \r\n                                                                    </td>\r\n                                                                    <td> \r\n                                                                        <vue-timepicker format=\"hh:mm a\" close-on-complete  manual-input  v-model=\"editForm.tasks[index].end_time\" :minute-interval=\"15\"></vue-timepicker> \r\n                                                                    </td>\r\n                                                                    <td>{{timeCalculation(index)}}</td>\r\n                                                                    <td> \r\n                                                                        <input class=\"form-control custom_checkbox\" v-model=\"editForm.tasks[index].top_priority\" style=\"border: 1px solid #efefef ; border-radius:  10px;\" type=\"checkbox\"\r\n                                                                        name=\"top_priority\" value=\"1\" ><label style=\"padding-left:5px ;\" for=\"Profession\"></label> \r\n                                                                    </td> \r\n                                                                    <td>\r\n                                                                        <button class=\"btn-success\"  type=\"button\" @click=\"item_add()\"  v-if=\"(editForm.tasks.length -1 == index)\" ><i class=\"bx bx-plus\"></i></button>\r\n                                                                        <button  class=\"btn-danger\"   type=\"button\" @click=\"item_removes(index , schedule)\"  ><i  class=\"bx bx-trash\"></i></button> \r\n                                                                    </td>\r\n                                                                </tr>\r\n                                                               \r\n                                                            </template>\r\n                                                            <template v-for=\"(type ,index2) in scheduleTypes\" >\r\n                                                                <tr :key=\"index2\">\r\n                                                                    <td colspan=\"2\" v-if=\"index2 == 0 \" :rowspan=\"scheduleTypes.length\"></td>\r\n                                                                    <td colspan=\"3\" class=\"text-right\">{{type.name}}</td>\r\n                                                                    <td>{{ timeConvert(getTypeTime(type.id)) }}</td>\r\n                                                                    <td>{{ getTypeTopPriority(type.id)}}</td>\r\n                                                                </tr>\r\n                                                            </template>\r\n                                                            <tr>\r\n                                                                <th colspan=\"4\"></th>\r\n                                                                <th class=\"text-right\">Total</th>\r\n                                                                <th>{{ timeConvert(getTypeTotalTime()) }}</th>\r\n                                                                <th>{{ getTypeTopTotalPriority()}}</th>\r\n                                                            </tr>\r\n                                                            <!-- <tr> \r\n                                                                <td colspan=\"3\">Function</td>\r\n                                                                <td colspan=\"2\">1h</td>\r\n                                                            </tr> -->\r\n                                                        </tbody>\r\n    \r\n                                                    </table> \r\n                                                </div> \r\n                                                 \r\n                                            <button type=\"submit\" class=\"btn btn-primary\">Submit</button>\r\n                                        </form>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </section>\r\n                <!-- Input Validation end -->\r\n            </div>\r\n        </div>\r\n    </div>\r\n    </div> \r\n</template>\r\n<script>\r\nimport axios from \"../../axios_instance\"; \r\nimport { Form } from \"vform\"; \r\n  import Datepicker from 'vuejs-datepicker';\r\n// import ClassicEditor from '@ckeditor/ckeditor5-build-classic' ;\r\nimport VueTimepicker from 'vue2-timepicker' \r\nimport 'vue2-timepicker/dist/VueTimepicker.css'\r\n//import Alignment from '@ckeditor/ckeditor5-alignment/src/alignment'; \r\n//import { VueEditor } from \"vue2-editor\";\r\nexport default {\r\n  props: { \r\n  },\r\n  components: {\r\n    VueTimepicker ,\r\n     Datepicker,\r\n\r\n   // VueEditor\r\n    // VueRecaptcha, facebookLogin \r\n  },\r\n  data() {\r\n    return {\r\n        // editor: ClassicEditor,\r\n        // editorData: '',\r\n        // editorConfig: {  \r\n        //     toolbar: {\r\n               \r\n        //                 items: [\r\n        //                     'bold',\r\n        //                     'italic',\r\n        //                     'link',\r\n        //                     'undo',\r\n        //                     'redo',\r\n        //                     'Code'\r\n        //                 ],\r\n                       \r\n        //             },\r\n                  \r\n             \r\n        // }, \r\n        \r\n        base_url: window.base_url,\r\n        api_url: window.api_url,    \r\n        DepartmentsItems : [], \r\n        id : this.$route.params.id,\r\n        token: this.$localStorage.get(\"d_token\"),  \r\n        user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n        role_id : '',\r\n        scheduleTypes : [],\r\n        scheduleTypes_allow : false ,\r\n        editForm: new Form({ \r\n            task: \"\",       \r\n            kra_id : \"\",\r\n            kpi_id : \"\",\r\n            mos_id : \"\",\r\n            date    : \"\",\r\n            top_priority : 0 ,\r\n            start_time : \"\",\r\n            end_time : \"\",\r\n            user_id : \"\",\r\n            tasks : [\r\n                        {\r\n                            schedule_type_id : 1  , \r\n                            task : \"\",\r\n                            start_time : \"08:30 am\",\r\n                            end_time : \"09:30 am\",\r\n                            duration : 0,\r\n                            top_priority : false ,\r\n                        } \r\n                    ], \r\n\r\n        }),\r\n        kraItem: [] ,  \r\n        kpiItem: [] ,  \r\n        mosItem: [] ,  \r\n    };\r\n  },\r\n  created() {\r\n    this.role_id = this.user_data.role_id ; \r\n    this.getItem(\"daily_schedules/\"+this.id).then(({ data }) => {  \r\n        if(data.success){\r\n            this.item =  data.data ;\r\n           // this.$refs.editor.setContent(this.item.task); \r\n            this.editForm.task =  this.item.task ; \r\n            this.editForm.status =  this.item.status ; \r\n            this.editForm.kra_id =  this.item.kra_id ; \r\n            this.editForm.kpi_id =  this.item.kpi_id ; \r\n            this.editForm.mos_id =  this.item.mos_id ; \r\n            this.editForm.date =  this.item.date ; \r\n            this.editForm.top_priority =  this.item.top_priority ; \r\n            this.editForm.start_time =  this.item.start_time ; \r\n            this.editForm.end_time =  this.item.end_time ; \r\n            this.editForm.user_id =  this.item.user_id ; \r\n            this.getKpi(this.item.kra_id);\r\n            this.getMos(this.item.kpi_id);\r\n            this.editForm.tasks = this.item.tasks ;\r\n        } \r\n    }); \r\n    if(this.role_id == 1 || this.role_id == 2 ||  this.role_id == 3 || this.role_id == 4 | this.role_id == 5){ \r\n        this.scheduleTypes_allow =  true ;\r\n        this.dailyScheduleTypes();\r\n    }\r\n      \r\n    this.getKRA()\r\n    this.dept();\r\n    \r\n  },\r\n  methods: { \r\n    timeCalculation(index){\r\n                let start_time = this.editForm.tasks[index].start_time ;\r\n                let end_time = this.editForm.tasks[index].end_time ;\r\n                if(start_time &&  end_time) { \r\n                    let total =  this.timeToMin(end_time) -  this.timeToMin(start_time) ;\r\n                    this.editForm.tasks[index].duration =  total ;\r\n                    return this.timeConvert(total) ;\r\n                }else{\r\n                    return '0m';\r\n                }  \r\n            },\r\n            timeConvert(n) {\r\n                var num = n;\r\n                var hours = (num / 60);\r\n                var rhours = Math.floor(hours);\r\n                var minutes = (hours - rhours) * 60;\r\n                var rminutes = Math.round(minutes);\r\n                return  ( rhours  ?  rhours + \"h \" : \"\" )+ ( rminutes ? rminutes + \"m\" : '');\r\n            },\r\n            timeToMin(start_time){\r\n                let start_time_end  = start_time.split(\" \");\r\n                let am_pm  = start_time_end[1] ;\r\n                let timeArray = start_time_end[0].split(\":\");\r\n                let h  = Number(timeArray[0])  ;\r\n                let m  = Number(timeArray[1]) \r\n                if(am_pm == 'pm' && h != 12){ h =  h+12 ; }\r\n                m = (h * 60 ) +  m ;\r\n                return m ; \r\n            },\r\n            getToDate() {\r\n                var date = new Date();\r\n                date.setDate(date.getDate() - 3);\r\n                var finalDate = date.getFullYear() + ', ' + (date.getMonth() + 1) + ', ' + date.getDate();\r\n                return finalDate;  \r\n            },\r\n            getTypeTime(id){\r\n                let totalTime  =  0 ;\r\n                this.editForm.tasks.forEach(element => {\r\n                    if(element.schedule_type_id == id){\r\n                        totalTime = totalTime +  Number(element.duration) \r\n                    } \r\n                });\r\n                return totalTime ;  \r\n            },\r\n            getTypeTotalTime(){\r\n                let totalTime  =  0 ;\r\n                this.editForm.tasks.forEach(element => { \r\n                        totalTime = totalTime +  Number(element.duration)  \r\n                });\r\n                return totalTime ;  \r\n            },\r\n            getTypeTopPriority(id){\r\n                let top_priority = 0 ;\r\n                this.editForm.tasks.forEach(element => {\r\n                    if(element.schedule_type_id  == id &&  element.top_priority == true){\r\n                        top_priority = top_priority + 1 ;\r\n                    } \r\n                });\r\n                return top_priority ? top_priority : '' ; \r\n            },\r\n            getTypeTopTotalPriority(){\r\n                let top_priority = 0 ;\r\n                this.editForm.tasks.forEach(element => {\r\n                    if(element.top_priority == true){\r\n                        top_priority = top_priority + 1 ; \r\n                    } \r\n                });\r\n                return top_priority ? top_priority :''; \r\n            },\r\n            //end \r\n            async dailyScheduleTypes(){\r\n                await axios.get(this.api_url + \"daily_schedule_types\", {\r\n                        headers: {\r\n                            \"Content-Type\": \"application/json\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    })\r\n                    .then(({\r\n                        data\r\n                    }) => {\r\n                        this.scheduleTypes = data.data;\r\n                        console.log(this.scheduleTypes);\r\n                    });\r\n            },\r\n            scheduleTypesName(id){  \r\n                for (let index = 0; index < this.scheduleTypes.length; index++) { \r\n                    if(this.scheduleTypes[index].id == id){\r\n                        return this.scheduleTypes[index].name ; \r\n                    }\r\n                }\r\n            },\r\n            item_add(){ \r\n                let newItem = {\r\n                        schedule_type_id : \"\",\r\n                        schedule_details : \"\",\r\n                        task : \"\",\r\n                        start_time : \"\",\r\n                        end_time : \"\",\r\n                        duration : 0,\r\n                        top_priority : false\r\n                    }; \r\n                this.editForm.tasks.push(newItem);\r\n            },\r\n            item_removes(index, item){\r\n                console.log(index);\r\n                console.log(item);\r\n                 \r\n                this.$swal({\r\n                    title: \"Are you sure?\",\r\n   