                    <tr>\r\n                      <td>MOS Name</td>\r\n                      <td>{{ item.mos_name }}</td>\r\n                    </tr>\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <!-- EDIT KRA MODAL -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"kraedit\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"updateKra()\">\r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KRA Name\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"hidden\" v-model=\"kra_id\" />\r\n                              <input type=\"text\" v-model=\"kra_name\" class=\"form-control\" placeholder=\"KRA Name\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KRA Weightage\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"kra_weight\" class=\"form-control\"\r\n                                placeholder=\"KRA WEIGHTAGE\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n       