ion\" name=\"kpi_id\" v-on:change=\"getItems()\"   v-model=\"filterForm.kpi_id\"  class=\"form-control\">\r\n                                            <option value=\"\">Select one</option>\r\n                                            <option  v-for=\"row in kpiItem\" :key=\"row.id\" :value=\"row.id\">{{ row.kpi_name}}</option>  \r\n                                        </select>\r\n                                    </div>\r\n                                </fieldset>\r\n                           </div>  \r\n                        </div>  \r\n                        </div>\r\n                        <div class=\"row\">\r\n                            <div class=\"col-12\">\r\n                                <div class=\"card\">\r\n                                    <div class=\"card-content\">\r\n                                        <div class=\"card-body card-dashboard\"> \r\n                                            <div class=\"table-responsive\">  \r\n                                                <table class=\"table table-bordered table-sm\">\r\n                                                    <thead class=\"thead-dark\"> \r\n                                                    <tr> \r\n                                                        <th v-if=\"filterForm.show_kra==1\">KRA</th>\r\n                                                        <!-- <th v-if=\"filterForm.show_kra==1\">Weightage</th> -->\r\n                                                        <th v-if=\"filterForm.show_kpi==1\">KPI</th>\r\n                                                        <th v-if=\"filterForm.show_kpi==1\">MOS</th>\r\n                                                        <!-- <th v-if=\"filterForm.show_mos==1\">MOS</th> \r\n                                                        <th>{{ filterForm.month !=''? 'm.Target' : filterForm.quarter == 1 ||  filterForm.quarter == 2 || filterForm.quarter == 3 || filterForm.quarter == 4 ? 'Q.Target' : filterFo